import sys, yaml
data = yaml.safe_load(sys.stdin)
fixed_exps = {}
for exp_id, exp in data.get('experiments', {}).items():
    if '_fixed' in exp_id:
        fixed_exps[exp_id] = {
            'status': exp.get('status'),
            'conclusion': exp.get('conclusion'),
            'metrics': exp.get('metrics'),
        }

# Sort by status
for status in ['DONE', 'RUNNING', 'QUEUED', 'PENDING', 'PREPARING']:
    exps = [(k,v) for k,v in fixed_exps.items() if v['status'] == status]
    if exps:
        print(f'\n=== {status} ({len(exps)}) ===')
        for k,v in sorted(exps):
            acc = v['metrics'].get('accuracy', '?') if v['metrics'] else '?'
            print(f'  {k}: conclusion={v[\"conclusion\"]}, acc={acc}')
